// Shepherd: reparse skills without reloading executable extensions or settings.
refreshSkills() {
    const previous = JSON.stringify(this.getSkills());
    const metadata = new Map(this.resourceMetadataByPath);
    let paths = this.lastSkillPaths;
    if (!this.noSkills) {
        const manager = this.packageManager;
        const accumulator = manager.createAccumulator();
        const global = this.settingsManager.getGlobalSettings();
        const project = this.settingsManager.getProjectSettings();
        const projectBase = join(this.cwd, CONFIG_DIR_NAME);
        manager.resolveLocalEntries(project.skills ?? [], "skills", accumulator.skills,
            { source: "local", scope: "project", origin: "top-level" }, projectBase);
        manager.resolveLocalEntries(global.skills ?? [], "skills", accumulator.skills,
            { source: "local", scope: "user", origin: "top-level" }, this.agentDir);
        manager.addAutoDiscoveredResources(accumulator, global, project, this.agentDir, projectBase);
        // Keep startup precedence: CLI extension resources, ranked local/package
        // resources, explicit --skill paths, then extension-discovered paths.
        const prefix = [], suffix = [];
        for (const path of this.lastSkillPaths) {
            const info = this.resourceMetadataByPath.get(path);
            if (info?.scope === "temporary") prefix.push(path);
            else if (info?.origin === "package") manager.addResource(accumulator.skills, path, info, true);
            else if (this.extensionSkillSourceInfos.has(path) || (info?.source !== "auto" && info?.source !== "local")) suffix.push(path);
        }
        const resources = manager.toResolvedPaths(accumulator).skills;
        for (const resource of resources) metadata.set(resource.path, resource.metadata);
        paths = this.mergePaths(prefix, [...resources.filter(r => r.enabled).map(r => this.mapSkillPath(r, metadata)), ...this.additionalSkillPaths, ...suffix]);
    }
    this.updateSkillsFromPaths(paths, metadata);
    return previous !== JSON.stringify(this.getSkills());
}
